using System.Text.Json;
using KL06;
int checks=0;void Check(bool value,string label){checks++;if(!value)throw new Exception("FAIL "+label);Console.WriteLine("PASS "+label);}void Reject(Action action,string label){try{action();}catch{Check(true,label);return;}Check(false,label);}
using var doc=JsonDocument.Parse("{}");Check(ControlPolicy.Exact(doc.RootElement),"empty strict params");
foreach(var pair in new[]{("10.0.0.1",true),("172.16.0.2",true),("172.31.255.254",true),("192.168.1.4",true),("127.0.0.1",false),("0.0.0.0",false),("172.32.0.1",false),("8.8.8.8",false),("010.0.0.1",false),("10.1",false),("10.0.0.999",false),("10.0.0.-1",false),("10.0.0.1\n",false)})Check(ControlPolicy.PrivateIPv4(pair.Item1)==pair.Item2,"LAN policy "+pair.Item1.Trim());
foreach(string raw in new[]{"{\"value\":true}","{\"value\":101}","{\"value\":-1}","{\"value\":\"50\"}","{\"value\":50,\"cmd\":\"bad\"}","{\"value\":50,\"value\":80}"}){using var d=JsonDocument.Parse(raw);Check(!ControlPolicy.Allowed("setVolume",d.RootElement),"reject invalid/ambiguous volume "+raw);}
foreach(string raw in new[]{"{\"value\":0}","{\"value\":50.5}","{\"value\":100}"}){using var d=JsonDocument.Parse(raw);Check(ControlPolicy.Allowed("setVolume",d.RootElement),"allow bounded numeric volume");Check(ControlPolicy.Describe("setVolume",d.RootElement).Contains(d.RootElement.GetProperty("value").ToString()),"confirmation describes actual volume");}
Check(!ControlPolicy.Allowed("shell",doc.RootElement),"no arbitrary shell");Check(!ControlPolicy.Allowed("setFan",doc.RootElement),"no fan-write method");
var backend=new FakeBackend();var disk=new FakeStorage();var journal=new PreferenceJournal(backend,disk);Check(disk.Raw is null,"read-only startup");journal.Apply("win-extensions");Check(backend.Values["win-extensions"]==0&&disk.Raw is not null,"journal-before-write apply");journal.Restore("win-extensions");Check(!backend.Values.ContainsKey("win-extensions"),"original absence restored");
backend.Values["win-extensions"]=1;journal.Apply("win-extensions");var reopened=new PreferenceJournal(backend,disk);reopened.Restore("win-extensions");Check(backend.Values["win-extensions"]==1,"exact original survives app restart");journal=reopened;
journal.Apply("win-extensions");backend.Values["win-extensions"]=3;Reject(()=>journal.Restore("win-extensions"),"external newer choice blocks restore");Reject(()=>journal.Apply("win-extensions"),"external newer choice blocks apply");Check(backend.Values["win-extensions"]==3,"conflict untouched");
var corrupt=new PreferenceJournal(backend,new FakeStorage{Raw="not json"});Reject(()=>corrupt.Apply("win-hidden"),"corrupt journal fails closed");Check(!backend.Values.ContainsKey("win-hidden"),"corrupt journal no write");
var failing=new PreferenceJournal(backend,new FakeStorage{Fail=true});Reject(()=>failing.Apply("win-hidden"),"failed save aborts before native write");Check(!backend.Values.ContainsKey("win-hidden"),"failed save no native write");
var managed=new FakeBackend{IsManaged=true};Reject(()=>new PreferenceJournal(managed,new FakeStorage()).Apply("win-hidden"),"managed policy blocks apply");
backend.Values["win-hidden"]=1;var noopDisk=new FakeStorage();new PreferenceJournal(backend,noopDisk).Apply("win-hidden");Check(noopDisk.Raw is null,"already configured does not invent baseline");
Reject(()=>journal.Apply("../../boot"),"path/arbitrary ID rejected");
foreach(string raw in new[]{"{\"Schema\":2,\"Entries\":{}}","{\"Schema\":1,\"Entries\":{\"unknown\":{\"OriginalExists\":false,\"Original\":null,\"Applied\":1}}}","{\"Schema\":1,\"Entries\":{\"win-hidden\":{\"OriginalExists\":true,\"Original\":null,\"Applied\":1}}}","{\"Schema\":1,\"Entries\":{\"win-hidden\":{\"OriginalExists\":false,\"Original\":null,\"Applied\":7}}}"})Reject(()=>new PreferenceJournal(new FakeBackend(),new FakeStorage{Raw=raw}).Apply("win-hidden"),"malformed journal rejected");
var interruptedBackend=new FakeBackend();var interruptedDisk=new FakeStorage{Raw="{\"Schema\":1,\"Entries\":{\"win-hidden\":{\"OriginalExists\":false,\"Original\":null,\"Applied\":1}}}"};new PreferenceJournal(interruptedBackend,interruptedDisk).Restore("win-hidden");Check(!interruptedBackend.Values.ContainsKey("win-hidden"),"interrupted before write can clear journal without writing");
Console.WriteLine($"{checks} portable C# policy/journal checks passed. No Windows registry, audio, power or hardware API was called.");
sealed class FakeBackend:IPreferenceBackend{internal Dictionary<string,int> Values=[];internal bool IsManaged;public int? Read(PreferenceSpec s)=>Values.TryGetValue(s.Id,out var n)?n:null;public void Write(PreferenceSpec s,int? n){if(n.HasValue)Values[s.Id]=n.Value;else Values.Remove(s.Id);}public bool Managed(PreferenceSpec s)=>IsManaged;}
sealed class FakeStorage:IJournalStorage{internal string? Raw;internal bool Fail;public string? Read()=>Raw;public void Save(string json){if(Fail)throw new IOException("synthetic");Raw=json;}}
